  ('mtn-001', 'Gunung Leuser', 3119, 'Grade 4 - Sangat Sulit', true, 'Buka', 3.7431, 97.1558, 'Gunung tertinggi di Aceh dalam kawasan Taman Nasional Gunung Leuser dengan belantara hutan hujan tropis primer dan keanekaragaman flora fauna langka.', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=800', 100, NOW()),
  ('mtn-002', 'Gunung Batur', 1717, 'Grade 1 - Mudah', false, 'Buka', -8.2424, 115.3753, 'Gunung berapi aktif di Kintamani Bali yang terkenal secara global dengan pemandangan golden sunrise di atas Danau Batur.', 'https://images.unsplash.com/photo-1518457607834-6e8d80c183c5?w=800', 400, NOW()),
  ('mtn-003', 'Gunung Kerinci', 3805, 'Grade 3 - Sulit', true, 'Waspada', -1.6967, 101.2642, 'Gunung berapi tertinggi di Indonesia dan atap tertinggi Pulau Sumatra di kawasan Taman Nasional Kerinci Seblat.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 250, NOW()),
  ('mtn-004', 'Gunung Gede', 2958, 'Grade 2 - Sedang', true, 'Buka', -6.7833, 106.9833, 'Gunung favorit di Jawa Barat dengan kawah aktif megah, telaga biru, dan padang edelweis legendaris Surya Kencana.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800', 300, NOW()),
  ('mtn-005', 'Gunung Pangrango', 3019, 'Grade 2 - Sedang', true, 'Buka', -6.77, 106.9639, 'Puncak kembar Gunung Gede yang asri dan tenang dengan padang edelweis Lembah Mandalawangi yang diabadikan Soe Hok Gie.', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=800', 300, NOW()),
  ('mtn-006', 'Gunung Bongkok', 975, 'Grade 1 - Mudah', false, 'Buka', -6.6578, 107.3514, 'Puncak batu andesit di Purwakarta yang menyuguhkan pemandangan Waduk Jatiluhur dan tebing batu eksotis.', 'https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=800', 200, NOW()),
  ('mtn-007', 'Gunung Cikuray', 2821, 'Grade 3 - Sulit', false, 'Buka', -7.3217, 107.86, 'Gunung kerucut tertinggi di Garut dengan julukan negeri di atas awan, menuntut persiapan fisik prima karena minim sumber air di jalur.', 'https://images.unsplash.com/photo-1434725039720-aaad6dd32dfe?w=800', 250, NOW()),
