  ('mtn-009', 'Gunung Burangrang', 2050, 'Grade 2 - Sedang', false, 'Buka', -6.7761, 107.5564, 'Sisa kaldera Gunung Sunda purba di Bandung Barat dengan medan tanjakan akar rapat yang menantang adrenalin.', 'https://images.unsplash.com/photo-1426604966848-d7adac402bff?w=800', 200, NOW()),
  ('mtn-010', 'Gunung Patuha', 2434, 'Grade 1 - Mudah', false, 'Buka', -7.1606, 107.4, 'Gunung di kawasan Ciwidey Bandung Selatan yang tersohor dengan danau kawah belerang putih toska Kawah Putih.', 'https://images.unsplash.com/photo-1472214103451-9374bd1c798e?w=800', 300, NOW()),
