  ('mtn-016', 'Gunung Kembang', 2340, 'Grade 2 - Sedang', false, 'Buka', -7.3756, 109.9194, 'Anak Gunung Sindoro di Wonosobo dengan aturan kebersihan standar internasional dan tanjakan curam tanpa henti.', 'https://images.unsplash.com/photo-1448375240586-882707db888b?w=800', 150, NOW()),
