  ('mtn-023', 'Gunung Sumbing', 3371, 'Grade 3 - Sulit', true, 'Buka', -7.3842, 110.07, 'Puncak tertinggi ketiga di Pulau Jawa dengan kawah kawah menakjubkan dan desa lereng terkenal Nepal van Java.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 350, NOW()),
