-- TimurLang - Supabase Query: Seed 46 Gunung & 112 Basecamp
-- Jalankan di Supabase Dashboard -> SQL Editor
-- ============================================

-- 1. Pastikan kolom-kolom baru tersedia di tabel users & logs
ALTER TABLE users ADD COLUMN IF NOT EXISTS is_biometric_enabled BOOLEAN DEFAULT FALSE;
ALTER TABLE users ADD COLUMN IF NOT EXISTS biometric_token TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS gunung_id TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS nama_basecamp TEXT;
ALTER TABLE sos_incident_logs ADD COLUMN IF NOT EXISTS basecamp_id TEXT;

-- 2. Bersihkan data lama dengan urutan relasi foreign key yang benar
-- (Hapus log insiden SOS dan riwayat perizinan terlebih dahulu agar tidak memblokir penghapusan gunung)
DELETE FROM sos_incident_logs;
DELETE FROM simaksi_permits;
DELETE FROM basecamp_posts;
DELETE FROM user_sessions WHERE user_id IN (SELECT id FROM users WHERE peran = 'basecamp');
DELETE FROM mountains;
DELETE FROM users WHERE peran = 'basecamp';

-- Perbarui foreign key sos_incident_logs agar di masa depan mendukung ON DELETE SET NULL
DO $$
BEGIN
  ALTER TABLE sos_incident_logs DROP CONSTRAINT IF EXISTS sos_incident_logs_gunung_id_fkey;
  ALTER TABLE sos_incident_logs ADD CONSTRAINT sos_incident_logs_gunung_id_fkey FOREIGN KEY (gunung_id) REFERENCES mountains(id) ON DELETE SET NULL;
EXCEPTION
  WHEN OTHERS THEN NULL;
END $$;

