-- 6. Pastikan kebijakan akses RLS Supabase mengizinkan pembacaan publik
DROP POLICY IF EXISTS "Public read mountains" ON mountains;
CREATE POLICY "Public read mountains" ON mountains FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public read basecamp_posts" ON basecamp_posts;
CREATE POLICY "Public read basecamp_posts" ON basecamp_posts FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public read basecamp users" ON users;
CREATE POLICY "Public read basecamp users" ON users FOR SELECT USING (peran = 'basecamp' OR auth.uid() = id);

